// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, uint256 fundAmount) public {
        vm.assume(fundAmount >= amount);
        vm.assume(fundAmount <= type(uint128).max);
        vm.assume(amount <= type(uint128).max);

        vm.deal(address(this), fundAmount);
        vm.prank(address(this));
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "funding failed");

        uint256 balBefore = address(c).balance;

        vm.prank(address(this));
        bool success = true;
        try c.withdraw(amount) {
        } catch {
            success = false;
        }

        uint256 balAfter = address(c).balance;

        assertTrue(!success || balAfter == balBefore - amount);
    }
}
